CREATE TABLE cash_operations(id UUID PRIMARY KEY,integrator_id VARCHAR(64) NOT NULL,idempotency_key VARCHAR(128) NOT NULL,fingerprint CHAR(64) NOT NULL,maker VARCHAR(128) NOT NULL,checker VARCHAR(128),wallet_id UUID NOT NULL,direction VARCHAR(3) NOT NULL CHECK(direction IN ('IN','OUT')),amount BIGINT NOT NULL CHECK(amount>0),evidence VARCHAR(128) NOT NULL,state VARCHAR(16) NOT NULL CHECK(state IN ('NEW','REQUESTED','APPROVED','POSTING','POSTED','ACCOUNTED','DISBURSED')),context JSONB,journal_id UUID,lease_token UUID,lease_until TIMESTAMPTZ,disbursed_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(integrator_id,idempotency_key),UNIQUE(integrator_id,evidence),CHECK(checker IS NULL OR checker<>maker));
CREATE FUNCTION protect_cash_intent() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF TG_OP='DELETE' OR (to_jsonb(NEW)-ARRAY['checker','state','context','journal_id','lease_token','lease_until','disbursed_at']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['checker','state','context','journal_id','lease_token','lease_until','disbursed_at']) THEN RAISE EXCEPTION 'Cash intent is immutable';END IF;
 IF OLD.checker IS NOT NULL AND NEW.checker IS DISTINCT FROM OLD.checker THEN RAISE EXCEPTION 'Checker is immutable';END IF;
 IF NEW.state<>OLD.state AND NOT ((OLD.state='NEW' AND NEW.state='REQUESTED') OR (OLD.state='REQUESTED' AND NEW.state='APPROVED' AND NEW.checker IS NOT NULL) OR (OLD.state='APPROVED' AND NEW.state='POSTING') OR (OLD.state='POSTING' AND NEW.state='POSTED' AND NEW.journal_id IS NOT NULL) OR (OLD.state='POSTED' AND NEW.state='ACCOUNTED') OR (OLD.state='ACCOUNTED' AND NEW.state='DISBURSED' AND NEW.direction='OUT')) THEN RAISE EXCEPTION 'Invalid cash transition';END IF;RETURN NEW;END $$;
CREATE TRIGGER cash_guard BEFORE UPDATE OR DELETE ON cash_operations FOR EACH ROW EXECUTE FUNCTION protect_cash_intent();
